      "Brown noise": {"es":"Ruido marrón","it":"Rumore marrone","de":"Braunes Rauschen","fr":"Bruit brun","tr":"Kahverengi gürültü","sr-Latn-RS":"Braon šum","pl":"Brązowy szum","nl":"Bruine ruis","cs":"Hnědý šum","he":"רעש חום","ar":"ضوضاء بنية","pt":"Ruído marrom","ro":"Zgomot maro","zh-CN":"褐噪音"},
      "Volume": {"es":"Volumen","it":"Volume","de":"Lautstärke","fr":"Volume","tr":"Ses düzeyi","sr-Latn-RS":"Jačina zvuka","pl":"Głośność","nl":"Volume","cs":"Hlasitost","he":"עוצמת קול","ar":"مستوى الصوت","pt":"Volume","ro":"Volum","zh-CN":"音量"},
      "How loud this widget plays its sound.": {"es":"A qué volumen reproduce este widget su sonido.","it":"Quanto forte questo widget riproduce il suo suono.","de":"Wie laut dieses Widget sein Geräusch abspielt.","fr":"Le volume du son de ce widget.","tr":"Bu widget'ın sesini ne kadar yüksek çaldığı.","sr-Latn-RS":"Koliko glasno ovaj vidžet pušta svoj zvuk.","pl":"Jak głośno ten widżet odtwarza dźwięk.","nl":"Hoe hard deze widget zijn geluid afspeelt.","cs":"Jak hlasitě tento widget hraje svůj zvuk.","he":"באיזו עוצמה הווידג'ט הזה משמיע את הצליל שלו.","ar":"مدى ارتفاع الصوت الذي تشغّله هذه الأداة.","pt":"O volume em que este widget toca o som.","ro":"Cât de tare redă acest widget sunetul.","zh-CN":"这个小组件播放声音的音量。"},
      "Empty shows Up next.": {"es":"Vacío muestra A continuación.","it":"Vuoto mostra A seguire.","de":"Leer zeigt Als Nächstes.","fr":"Vide affiche À suivre.","tr":"Boş bırakılırsa \"Sıradaki\" görünür.","sr-Latn-RS":"Prazno prikazuje \"Sledeće\".","pl":"Puste pokazuje Następne.","nl":"Leeg toont Hierna.","cs":"Prázdné ukáže \"Další na řadě\".","he":"ריק מציג \"הבא בתור\".","ar":"إذا تُرك فارغًا يظهر \"التالي\".","pt":"Vazio mostra A seguir.","ro":"Gol arată Urmează.","zh-CN":"留空则显示“接下来”。"},
