      "Middle": {"es":"Centro","it":"Centro","de":"Mitte","fr":"Centre","tr":"Orta","sr-Latn-RS":"Sredina","pl":"Na środku","nl":"Midden","cs":"Uprostřed","he":"אמצע","ar":"الوسط","pt":"Centro","ro":"Centru","zh-CN":"居中"},
      "Right": {"es":"Derecha","it":"Destra","de":"Rechts","fr":"Droite","tr":"Sağ","sr-Latn-RS":"Desno","pl":"Do prawej","nl":"Rechts","cs":"Vpravo","he":"ימין","ar":"يمين","pt":"Direita","ro":"Dreapta","zh-CN":"靠右"},
      "Glass from": {"es":"Cristal de","it":"Vetro da","de":"Glas aus","fr":"Verre avec","tr":"Cam görüntüsü","sr-Latn-RS":"Staklo od","pl":"Szkło ze zdjęcia","nl":"Glas met","cs":"Sklo z","he":"הזכוכית מ","ar":"الزجاج من","pt":"Vidro de","ro":"Sticlă din","zh-CN":"玻璃里的照片"},
      "The photo inside the digits.": {"es":"La foto dentro de los números.","it":"La foto dentro le cifre.","de":"Das Foto in den Ziffern.","fr":"La photo dans les chiffres.","tr":"Rakamların içindeki fotoğraf.","sr-Latn-RS":"Fotografija unutar cifara.","pl":"Zdjęcie wewnątrz cyfr.","nl":"De foto in de cijfers.","cs":"Fotka uvnitř číslic.","he":"התמונה שבתוך הספרות.","ar":"الصورة داخل الأرقام.","pt":"A foto dentro dos números.","ro":"Fotografia din interiorul cifrelor.","zh-CN":"数字里面的照片。"},
      "This home's scene": {"es":"La escena de esta casa","it":"La scena di questa casa","de":"Szene dieses Zuhauses","fr":"La scène de ce foyer","tr":"Bu evin sahnesi","sr-Latn-RS":"Scena ovog doma","pl":"Scena tego domu","nl":"Beeld van dit huis","cs":"Scéna této domácnosti","he":"הסצנה של הבית הזה","ar":"مشهد هذا المنزل","pt":"A cena desta casa","ro":"Scena acestei case","zh-CN":"这个家的场景"},
